import{_ as r,a0 as n,w as l,s as p,ao as d,I as o,x as a,a1 as i,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"20個關於Postfix的面試題 | LCTT x X-CMD","titleTemplate":false,"description":"20個關於Postfix的面試題 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"20個關於Postfix的面試題 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"20個關於Postfix的面試題 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20140826 20 Postfix Interview Questions and Answers","title":"20個關於Postfix的面試題","tag":"201412","desc":""},"relativePath":"201412/20140826 20 Postfix Interview Questions and Answers.md","filePath":"[post].md"}'),f={name:"201412/20140826 20 Postfix Interview Questions and Answers.md"};function h(x,e,m,P,c,u){const t=n("Link");return l(),p("div",null,[e[13]||(e[13]=d(`<h1 id="_20個關於postfix的面試題" tabindex="-1">20個關於Postfix的面試題 <a class="header-anchor" href="#_20個關於postfix的面試題" aria-label="Permalink to “20個關於Postfix的面試題”">​</a></h1><h3 id="問題1-什麼是-postfix-它的默認端口是多少" tabindex="-1">問題1：什麼是 Postfix，它的默認端口是多少？ <a class="header-anchor" href="#問題1-什麼是-postfix-它的默認端口是多少" aria-label="Permalink to “問題1：什麼是 Postfix，它的默認端口是多少？”">​</a></h3><p>答：Postfix 是一個開源的 MTA（郵件傳送代理，英文名：Mail Transfer Agent）,用於轉發 email。相信很多人知道 Sendmail，而 Postfix 是它的替代品。默認端口是25。</p><h3 id="問題2-postfix-和-sendmail-有什麼區別" tabindex="-1">問題2：Postfix 和 Sendmail 有什麼區別？ <a class="header-anchor" href="#問題2-postfix-和-sendmail-有什麼區別" aria-label="Permalink to “問題2：Postfix 和 Sendmail 有什麼區別？”">​</a></h3><p>答：Postfix 使用模組化設計，由多個獨立的可執行程序組成；而 Sendmail 被設計成有一個強大的後台進程提供所有服務。</p><h3 id="問題3-什麼是-mta-它在郵件系統中扮演什麼角色" tabindex="-1">問題3：什麼是 MTA，它在郵件系統中扮演什麼角色？ <a class="header-anchor" href="#問題3-什麼是-mta-它在郵件系統中扮演什麼角色" aria-label="Permalink to “問題3：什麼是 MTA，它在郵件系統中扮演什麼角色？”">​</a></h3><p>答：MTA 是 Mail Transfer Agent （郵件傳輸代理）的縮寫。MTA 負責接收和發送郵件、確定發送路徑和地址重寫（LCTT譯註：address rewriting，就是完善發送地址，比如將“username”這個地址重寫為“username@example.com”）。本地轉發就是將郵件發送給 MDA。Qmail、Postix、Sendmail 都是 MTA。</p><h3 id="問題4-什麼是-mda" tabindex="-1">問題4：什麼是 MDA？ <a class="header-anchor" href="#問題4-什麼是-mda" aria-label="Permalink to “問題4：什麼是 MDA？”">​</a></h3><p>答：MDA 是 Mail Delivery Agent （郵件投遞代理）的縮寫。MDA 這個程序用於從 MTA 獲取郵件並投遞至本地收件人的郵箱。MDA 通常可以過濾郵件或為郵件分類。一個 MDA 也能決定一封郵件是否需要轉發到另一個郵箱地址。Procmail 就是一個 MDA。</p><h3 id="問題5-什麼是-mua" tabindex="-1">問題5：什麼是 MUA？ <a class="header-anchor" href="#問題5-什麼是-mua" aria-label="Permalink to “問題5：什麼是 MUA？”">​</a></h3><p>答：MUA 是 Mail User Agent （郵件用户代理）的縮寫。MUA 是一個郵件客户端軟件，可以用來寫郵件、發送郵件、接收郵件。發送郵件時使用的是 MTA；接收郵件時可以從郵件存儲區直接收取，也可以通過 POP/IMAP 服務器間接收取。Outlook、Thunkerbird、Evolution 都是 MUA。</p><h3 id="問題6-郵件服務器裏-postmaster-的作用是什麼" tabindex="-1">問題6：郵件服務器裏 postmaster 的作用是什麼？ <a class="header-anchor" href="#問題6-郵件服務器裏-postmaster-的作用是什麼" aria-label="Permalink to “問題6：郵件服務器裏 postmaster 的作用是什麼？”">​</a></h3><p>答：郵件管理者一般就是 postmaster。一個 postmaster 的責任就是保證郵件系統正常工作、更新系統配置、添加/刪除郵箱帳號，以及其他工作。每個域中必須存在一個 postmaster 的別名（LCTT譯註：postmaster 別名用於接受一些其它服務器/用户對該郵件系統的溝通郵件，如關於垃圾郵件拒收的投訴等，通常都會直接被郵件服務器的管理員所接受。一些系統錯誤和提示的郵件，也往往以postmaster 作為發件人），用於將郵件發往正確的用户。</p><h3 id="問題7-postfix-都有些什麼重要的進程" tabindex="-1">問題7：Postfix 都有些什麼重要的進程？ <a class="header-anchor" href="#問題7-postfix-都有些什麼重要的進程" aria-label="Permalink to “問題7：Postfix 都有些什麼重要的進程？”">​</a></h3><p>答：以下是 Postfix 郵件系統裏最重要的後台進程列表：</p><ul><li><strong>master</strong>：這條進程是 Postfix 郵件系統的大腦，它產生所有其他進程。</li><li><strong>smtpd</strong>：作為服務器端程序處理所有外部連進來的請求。</li><li><strong>smtp</strong>：作為客户端程序處理所有對外發起連接的請求。</li><li><strong>qmgr</strong>：它是 Postfix 郵件系統的心臟，處理和控制郵件隊列裏面的所有消息。</li><li><strong>local</strong>：這是 Postfix 自有的本地投遞代理MDA，就是它負責把郵件保存到郵箱裏。</li></ul><h3 id="問題8-postfix-服務器的配置文件是什麼" tabindex="-1">問題8：Postfix 服務器的配置文件是什麼？ <a class="header-anchor" href="#問題8-postfix-服務器的配置文件是什麼" aria-label="Permalink to “問題8：Postfix 服務器的配置文件是什麼？”">​</a></h3><p>答：有兩個主要配置文件：</p><ul><li><strong>/etc/postfix/main.cf</strong>：這個文件保存全局配置信息，所有進程都會用到，除非這些配置在 master.cf 文件中被重新設置了。</li><li><strong>/etc/postfix/master.cf</strong>：這個文件保存了額外的進程運行時環境參數，在 main.cf 文件中定義的配置可能會被本文件的配置覆蓋掉。</li></ul><h3 id="問題9-如何將-postfix-重啓以及設為開機啓動" tabindex="-1">問題9：如何將 Postfix 重啓以及設為開機啓動？ <a class="header-anchor" href="#問題9-如何將-postfix-重啓以及設為開機啓動" aria-label="Permalink to “問題9：如何將 Postfix 重啓以及設為開機啓動？”">​</a></h3><p>答：使用這個命令重啓：<code>service postfix restart</code>；使用這個命令設為開機啓動：<code>chkconfig postfix on</code></p><h3 id="問題10-怎麼查看-postfix-的郵件隊列" tabindex="-1">問題10：怎麼查看 Postfix 的郵件隊列？ <a class="header-anchor" href="#問題10-怎麼查看-postfix-的郵件隊列" aria-label="Permalink to “問題10：怎麼查看 Postfix 的郵件隊列？”">​</a></h3><p>答：Postfix 維護兩個隊列：未決郵件隊列（pending mails queue）和等待郵件隊列（deferred mail queue）。等待隊列包含了暫時發送失敗、需要重新發送的郵件，Postfix 會定期重發（默認5分鐘，可自定義設置）。（LCTT譯註：其實 Postfix 維護5個隊列：輸入隊列，郵件進入 Postfix 系統的第一站；活動隊列，qmgr 將輸入隊列的郵件移到活動隊列；等待隊列，保存暫時不能發送出去的郵件；故障隊列，保存受損或無法解讀的郵件；保留隊列，將郵件無限期留在 Postfix 隊列系統中。）</p><p>列出郵件隊列裏面所有郵件：</p><pre><code># postqueue -p
</code></pre><p>保存郵件隊列名單：</p><pre><code># postqueue -p &gt; /mnt/queue-backup.txt
</code></pre><p>讓 Postfix 馬上處理隊列：</p><pre><code># postqueue -f
</code></pre><h3 id="問題11-如何刪除郵件隊列裏面的郵件" tabindex="-1">問題11：如何刪除郵件隊列裏面的郵件？ <a class="header-anchor" href="#問題11-如何刪除郵件隊列裏面的郵件" aria-label="Permalink to “問題11：如何刪除郵件隊列裏面的郵件？”">​</a></h3><p>答：以下命令刪除所有郵件：</p><pre><code># postsuper -d ALL
</code></pre><p>以下命令只刪除等待隊列中的郵件：</p><pre><code># postsuper -d ALL deferred
</code></pre><h3 id="問題12-如何通過命令來檢查-postfix-配置信息" tabindex="-1">問題12：如何通過命令來檢查 Postfix 配置信息？ <a class="header-anchor" href="#問題12-如何通過命令來檢查-postfix-配置信息" aria-label="Permalink to “問題12：如何通過命令來檢查 Postfix 配置信息？”">​</a></h3><p>答：使用<code>postconf -n</code>命令可以查看，它會過濾掉配置文件裏面被註釋掉的配置信息。</p><h3 id="問題13-實時查看郵件日誌要用什麼命令" tabindex="-1">問題13：實時查看郵件日誌要用什麼命令？ <a class="header-anchor" href="#問題13-實時查看郵件日誌要用什麼命令" aria-label="Permalink to “問題13：實時查看郵件日誌要用什麼命令？”">​</a></h3><p>答：<code>tail -f /var/log/maillog</code> 或 <code>tailf /var/log/maillog</code></p><h3 id="問題14-如何通過命令列發送測試郵件" tabindex="-1">問題14：如何通過命令列發送測試郵件？ <a class="header-anchor" href="#問題14-如何通過命令列發送測試郵件" aria-label="Permalink to “問題14：如何通過命令列發送測試郵件？”">​</a></h3><p>答：參考下面的命令：</p><pre><code># echo &quot;Test mail from postfix&quot; | mail -s &quot;Plz ignore&quot; info@something.com
</code></pre><h3 id="問題15-什麼是-開放郵件轉發-open-relay" tabindex="-1">問題15：什麼是“開放郵件轉發（Open Relay）”？ <a class="header-anchor" href="#問題15-什麼是-開放郵件轉發-open-relay" aria-label="Permalink to “問題15：什麼是“開放郵件轉發（Open Relay）”？”">​</a></h3><p>答：開放郵件轉發是 SMTP 服務器的一項設定，允許因特網上任意的其他用户能通過該服務器轉發郵件，而不是直接發送到某個帳號的服務器或只允許授權用户通過它來發送郵件。過去，這項功能在許多郵件服務器中都是默認開啓的，但是現在已經不再流行了，因為郵件轉發會導致大量垃圾郵件和病毒郵件在網絡上肆虐。</p><h3 id="問題16-什麼是-postfix-上的郵件轉發主機" tabindex="-1">問題16：什麼是 Postfix 上的郵件轉發主機？ <a class="header-anchor" href="#問題16-什麼是-postfix-上的郵件轉發主機" aria-label="Permalink to “問題16：什麼是 Postfix 上的郵件轉發主機？”">​</a></h3><p>答：轉發主機是 SMTP 的地址，如果在配置文件中有配置，那麼所有輸入郵件都將被 SMTP 服務器轉發。</p><h3 id="問題17-什麼是灰名單" tabindex="-1">問題17：什麼是灰名單？ <a class="header-anchor" href="#問題17-什麼是灰名單" aria-label="Permalink to “問題17：什麼是灰名單？”">​</a></h3><p>答：灰名單（LCTT譯註：介於白名單和黑名單之間）是一種用於攔截垃圾郵件的技術。一個 MTA 使用灰名單時就會“暫時拒絕”未被識別的發送者發來的所有郵件。如果郵件是正當合理的，發起者會在一段時間後重新發送，然後這份郵件就能被接收。（LCTT譯註：灰名單基於這樣一個事實，就是大多數的垃圾郵件服務器和殭屍網絡的郵件只發送一次，而會忽略要求它們在一定的時間間隔後再次發送的請求。）</p><h3 id="問題18-郵件系統中-spf-記錄有什麼重要作用" tabindex="-1">問題18：郵件系統中 SPF 記錄有什麼重要作用？ <a class="header-anchor" href="#問題18-郵件系統中-spf-記錄有什麼重要作用" aria-label="Permalink to “問題18：郵件系統中 SPF 記錄有什麼重要作用？”">​</a></h3><p>答：SPF 是 Sender Policy Framework 的縮寫，用於幫助郵件域的擁有者確認發送方是否來自他們的域，目的是其他郵件系統能夠保證發送方在發送郵件時來自經過授權的來源 —— 這種方法可以減小遇到郵件地址欺騙、網絡釣魚和垃圾郵件的風險。</p><h3 id="問題19-郵件系統中-dkim-有什麼用處" tabindex="-1">問題19：郵件系統中 DKIM 有什麼用處？ <a class="header-anchor" href="#問題19-郵件系統中-dkim-有什麼用處" aria-label="Permalink to “問題19：郵件系統中 DKIM 有什麼用處？”">​</a></h3><p>答：域名密匙是一套電子郵件身份認證系統，用於驗證郵件發送方的 DNS 域和郵件的完整性。域名密匙規範採用互聯網電子郵件認證技術，建立了一套加強版協議：域名密匙識別郵件（就是 DKIM）。</p><h3 id="問題20-郵件系統中-assp-的規則是什麼" tabindex="-1">問題20：郵件系統中 ASSP 的規則是什麼？ <a class="header-anchor" href="#問題20-郵件系統中-assp-的規則是什麼" aria-label="Permalink to “問題20：郵件系統中 ASSP 的規則是什麼？”">​</a></h3><p>答：ASSP(Anti-Spam SMTP Proxy，反垃圾代理) 是一個網關服務器，安裝在你的 MTA 前面，通過自建白名單、自動學習貝葉斯算法、灰名單、DNS 黑名單（DNSBL）、DNS 白名單（DNSWL）、URI黑名單（URIBL）、SPF、SRS、Backscatter、病毒掃描功能、附件阻攔功能、基於發送方等多種方法來反垃圾郵件。</p><hr>`,54)),o("p",null,[e[1]||(e[1]=a("via: ",-1)),i(t,{href:"http://www.linuxtechi.com/postfix-interview-questions-answers/"},{default:s(()=>[...e[0]||(e[0]=[a("http://www.linuxtechi.com/postfix-interview-questions-answers/",-1)])]),_:1})]),o("p",null,[e[5]||(e[5]=a("作者：",-1)),i(t,{href:"http://www.linuxtechi.com/author/pradeep/"},{default:s(()=>[...e[2]||(e[2]=[a("Pradeep Kumar",-1)])]),_:1}),e[6]||(e[6]=a(" 譯者：",-1)),i(t,{href:"https://github.com/bazz2"},{default:s(()=>[...e[3]||(e[3]=[a("bazz2",-1)])]),_:1}),e[7]||(e[7]=a(" 校對：",-1)),i(t,{href:"https://github.com/wxy"},{default:s(()=>[...e[4]||(e[4]=[a("wxy",-1)])]),_:1})]),o("p",null,[e[10]||(e[10]=a("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[8]||(e[8]=[a("LCTT",-1)])]),_:1}),e[11]||(e[11]=a(" 原創翻譯，",-1)),i(t,{href:"http://linux.cn/"},{default:s(()=>[...e[9]||(e[9]=[a("Linux中國",-1)])]),_:1}),e[12]||(e[12]=a(" 榮譽推出",-1))])])}const M=r(f,[["render",h]]);export{A as __pageData,M as default};
